/**
 * @param {number} target
 * @return {number}
 */
Array.prototype.upperBound = function(target) {
    // `this` is the array the method is called on (so avoid arrow functions here)
    let left = 0, right = this.length - 1;

    // Invariant: the answer (if any) lies in [left, right]
    while (left < right) {
        // Bias mid toward the right so left = mid always makes progress
        const mid = left + Math.ceil((right - left) / 2);
        if (this[mid] > target) {
            right = mid - 1;      // mid is too big, discard it
        } else {
            left = mid;           // this[mid] <= target, last occurrence is at mid or later
        }
    }

    // left === right (or the array is empty, where this[0] is undefined)
    return this[left] === target ? left : -1;
};

// [3,4,5].upperBound(5); // 2
// [1,4,5].upperBound(2); // -1
// [3,4,6,6,6,6,7].upperBound(6) // 5
